#include <cstdio>
#include <algorithm>

using namespace std;

int dp[330];
int s, d, m;
int k[110], w[110][55], p[110][55], f[110];

int main() {
    while (scanf("%d %d %d", &s, &d, &m) == 3) {
        for (int i = 0; i < s; i++) {
            scanf("%d", &k[i]);
            for (int j = 0; j < k[i]; j++) 
                scanf("%d %d", &w[i][j], &p[i][j]);
        }
        for (int i = 0; i < d; i++) 
            scanf("%d", &f[i]);

        fill(dp, dp + m + 1, -1);
        dp[0] = 0;

        for (int i = 0; i < d; i++) {
            int curr_f = f[i];
            for (int x = 0; x < k[curr_f]; x++) {
                int v = p[curr_f][x], c = w[curr_f][x];
                for (int j = m - v; j >= 0; j--) {
                    if (dp[j] >= 0) 
                        dp[j + v] = max(dp[j + v], dp[j] + c);
                }
            }
        }

        int ans = max_element(dp + 1, dp + m + 1) - dp;
        printf("%d %d\n", dp[ans], ans);
    }
}

