        }
        for (int i = 0; i < d; i++) scanf("%d", &f[i]);

        fill(dp, dp + m + 1, 0); // Initialize dp with 0 instead of -1.

        for (int i = 0; i < d; i++) {
            for (int x = 0; x < k[f[i]]; x++) {
                int v = p[f[i]][x], c = w[f[i]][x];
                // Modify to iterate from m down to the current weight.
                for (int j = m; j >= v; j--) { 
                    dp[j] = max(dp[j], dp[j - v] + c);
                }
            }
        }

        int ans = max_element(dp + 1, dp + m + 1) - dp;
        printf("%d %d\n", dp[ans], ans);
    }
}

