        for (int i = 0; i < d; i++) scanf("%d", &f[i]);

        vector<int> dp(m + 1, -1);
        dp[0] = 0;

        for (int i = 0; i < d; i++) {
            for (int x = 0; x < k[f[i]]; x++) {
                int v = p[f[i]][x], c = w[f[i]][x];
                for (int j = m - v; j >= 0; j--) {
                    if (dp[j] >= 0) dp[j + v] = max(dp[j + v], dp[j] + c);
                }
            }
        }

        int ans = max_element(dp.begin() + 1, dp.end()) - dp.begin();
        printf("%d %d\n", dp[ans], ans);
    }
}

