int main() {
    int s, d, m;
    while (cin >> s >> d >> m) {
        vector<int> k(s);
        vector<vector<int>> w(s);
        vector<vector<int>> p(s);
        vector<int> f(d);

        // Reserve space for the vectors to avoid repeated allocations
        for (int i = 0; i < s; i++) {
            cin >> k[i];
            w[i].reserve(k[i]);
            p[i].reserve(k[i]);
            for (int j = 0; j < k[i]; j++) {
                int weight, profit;
                cin >> weight >> profit;
                w[i].emplace_back(weight);
                p[i].emplace_back(profit);
            }
        }
        for (int i = 0; i < d; i++) cin >> f[i];

        vector<int> dp(m + 1, -1);
        dp[0] = 0;

        for (int i = 0; i < d; i++) {
            int current_f = f[i];
            for (int x = 0; x < k[current_f]; x++) {
                int v = p[current_f][x], c = w[current_f][x];
                for (int j = m - v; j >= 0; j--) {
                    if (dp[j] >= 0) dp[j + v] = max(dp[j + v], dp[j] + c);
                }
            }
        }

        int ans = max_element(dp.begin() + 1, dp.end()) - dp.begin();
        cout << dp[ans] << " " << ans << endl;
    }
}

